"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { PlusIcon, Calendar, Clock, Users, X } from "lucide-react";
import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface Excursion {
  id: string;
  Titulo_Salida: string;
  Como_Llegar: string;
  Que_Llevar: string[];
  Cuanto_Dura: string;
}

export default function ExcursaUBAPage() {
  const [excursions, setExcursions] = useState<Excursion[]>([]);
  const [newExcursion, setNewExcursion] = useState<Excursion>({
    id: "",
    Titulo_Salida: "",
    Como_Llegar: "",
    Que_Llevar: [],
    Cuanto_Dura: "",
  });

  const [currentItem, setCurrentItem] = useState("");

  // Carga inicial de excursiones
  useEffect(() => {
    fetch("http://127.0.0.1:8090/api/collections/Salidas_Alumnos/records?page=1&perPage=30")
      .then((res) => res.json())
      .then((data) => {
        const parsed = data.items.map((item: any) => ({
          id: item.id,
          Titulo_Salida: item.Titulo_Salida,
          Como_Llegar: item.Como_Llegar,
          Que_Llevar: item.Que_Llevar || [],
          Cuanto_Dura: item.Cuanto_Dura,
        }));
        setExcursions(parsed);
      })
      .catch(console.error);
  }, []);

  // Agregar ítem a Que_Llevar
  const handleAddItem = () => {
    if (currentItem) {
      setNewExcursion({
        ...newExcursion,
        Que_Llevar: [...newExcursion.Que_Llevar, currentItem],
      });
      setCurrentItem("");
    }
  };

  // Eliminar ítem de Que_Llevar
  const handleRemoveItem = (index: number) => {
    setNewExcursion({
      ...newExcursion,
      Que_Llevar: newExcursion.Que_Llevar.filter((_, i) => i !== index),
    });
  };

  // Agregar nueva propuesta
  const handleAddPropuesta = () => {
    if (
      newExcursion.Titulo_Salida &&
      newExcursion.Como_Llegar &&
      newExcursion.Cuanto_Dura
    ) {
      fetch("http://127.0.0.1:8090/api/collections/Salidas_Alumnos/records", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          Titulo_Salida: newExcursion.Titulo_Salida,
          Como_Llegar: newExcursion.Como_Llegar,
          Que_Llevar: newExcursion.Que_Llevar,
          Cuanto_Dura: newExcursion.Cuanto_Dura,
        }),
      })
        .then((res) => res.json())
        .then((data) => {
          console.log(data)
          setExcursions([...excursions, { ...newExcursion, id: data.id }]);
          setNewExcursion({ id: "", Titulo_Salida: "", Como_Llegar: "", Que_Llevar: [], Cuanto_Dura: "" });
          setCurrentItem("");
          alert("Nueva propuesta agregada exitosamente.");
        })
        .catch(console.error);
    }
  };

  const cardColors = [
    "bg-[oklch(0.35_0.12_255)]",
    "bg-[oklch(0.75_0.08_220)]",
    "bg-[oklch(0.65_0.15_210)]",
    "bg-[oklch(0.50_0.10_240)]",
  ];

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="mx-auto max-w-6xl">
        {/* HEADER */}
        <header className="mb-10 text-center">
          <div className="mb-3 flex items-center justify-center gap-4">
            <img
              src="https://hebbkx1anhila5yf.public.blob.vercel-storage.com/imagen-OlQUL6sPmlnGOi07AcEqtFxPWo5KND.png"
              alt="Logo UBA"
              className="h-16 w-16 md:h-20 md:w-20"
            />
            <h1 className="font-bold tracking-tight text-[oklch(0.27_0.12_255)] text-5xl md:text-6xl">
              ExcursaUBA
            </h1>
          </div>
          <p className="text-balance text-foreground/80 text-lg">
            Sistema de organización de viajes y salidas grupales - Escuela Técnica UBA
          </p>
        </header>

        {/* TARJETAS */}
        <div className="mb-8 grid gap-6 md:grid-cols-2">
          {excursions.map((excursion, index) => (
            <Card
              key={excursion.id}
              className={`border-4 border-white shadow-lg transition-all hover:shadow-2xl ${
                cardColors[index % cardColors.length]
              }`}
            >
              <CardHeader className="border-b-2 border-white/30 bg-white/10">
                <CardTitle className="text-center text-2xl font-bold text-white">
                  {excursion.Titulo_Salida}
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-5 pt-6">
                <p className="text-white font-bold">Cómo llegar:</p>
                <p className="text-white/80">{excursion.Como_Llegar}</p>

                <p className="text-white font-bold mt-2">Qué llevar:</p>
                <ul className="list-disc list-inside text-white/80">
                  {excursion.Que_Llevar.map((item, i) => (
                    <li key={i}>{item}</li>
                  ))}
                </ul>

                <p className="text-white font-bold mt-2">Duración:</p>
                <p className="text-white/80">{excursion.Cuanto_Dura}</p>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Botón "Agregar Nueva Propuesta..." */}
        <div className="mt-8 flex flex-col items-center gap-4">
          {/* Input para nuevo item */}
          <div className="flex w-full max-w-md gap-2">
            <Input
              placeholder="Nuevo ítem a llevar"
              value={currentItem}
              onChange={(e) => setCurrentItem(e.target.value)}
            />
            <Button onClick={handleAddItem}>Agregar</Button>
          </div>

          <Button
            size="lg"
            className="w-full max-w-md border-4 border-white bg-[oklch(0.65_0.15_210)] py-8 text-lg font-bold text-white shadow-lg"
            onClick={handleAddPropuesta}
          >
            <PlusIcon className="mr-2 h-6 w-6" />
            Agregar Nueva Propuesta...
          </Button>
        </div>
      </div>
    </div>
  );
}